import random
from problems import SubsetSum, Partition
from reduce import reduce

def solve_ss(nums, t):
    if t < 0: return False
    if t == 0: return True
    bits = 1
    for a in nums:
        bits |= bits << a
    return (bits >> t) & 1 == 1

def solve_part(nums):
    S = sum(nums)
    if S % 2: return False
    bits = 1
    for a in nums:
        bits |= bits << a
    return (bits >> (S//2)) & 1 == 1

def solve_ss_set(nums, t):
    if t < 0: return False
    if t == 0: return True
    reach = {0}
    for a in nums:
        reach |= {s+a for s in reach}
    return t in reach

def solve_part_set(nums):
    S = sum(nums)
    if S % 2: return False
    reach = {0}
    for a in nums:
        reach |= {s+a for s in reach}
    return S//2 in reach

rng = random.Random(999)
run = passed = 0
for _ in range(3000):
    n = rng.randint(0, 14)
    nums = [rng.choice([0,1,2,3,7,13,50,200]) for _ in range(n)]
    S = sum(nums)
    t = rng.randint(-2, S+2)
    inst = {"numbers": nums, "target": t}
    out = reduce(inst)
    Partition.validate(out)
    run += 1
    if solve_ss(nums, t) == solve_part(out["numbers"]):
        passed += 1
    else:
        print("MISMATCH", inst, out)

for inst in [{"numbers":[10**30, 10**30], "target":10**30},
