    out = reduce(inst)
    Partition.validate(out)
    run += 1
    if solve_ss_set(inst["numbers"], inst["target"]) == solve_part_set(out["numbers"]):
        passed += 1
    else:
        print("MISMATCH", inst, out)
print(f"extra_run={run} extra_passed={passed}")
EOF
